INSERT OR IGNORE INTO memory_items(stable_id,kind,source,title,content,artifact_path,source_hash,tags,weight) VALUES('project:antigravity:cli-surface-v1','project_tool','seed://antigravity/cli-surface','Google Antigravity command surface','Snapshot date: 2026-07-15. Commands and tools: Agent Manager, Editor/Tab, @ context references, slash commands, terminal execution policy, skills, MCP servers, artifacts, agent tasks and reviews; optional agy CLI. Configuration model: ~/.gemini/config/mcp_config.json, Antigravity settings, .antigravityrules where supported. Source: https://www.antigravity.google/docs/settings and /docs/overview (verified 2026-07-15).','https://www.antigravity.google/docs/settings and /docs/overview (verified 2026-07-15)','be3c2bf31335e4f8e4df35800769bd33900765cd32325bd1172149c4f3cdc419','antigravity,cli,command-surface,provenance',2.2);
INSERT OR IGNORE INTO memory_items(stable_id,kind,source,title,content,artifact_path,source_hash,tags,weight) VALUES('project:antigravity:config-model-v1','project_doc','seed://antigravity/config-model','Google Antigravity command surface configuration model','Snapshot date: 2026-07-15. Canonical configuration paths: ~/.gemini/config/mcp_config.json, Antigravity settings, .antigravityrules where supported. Registration is additive, idempotent, and must preserve user-owned keys, hooks, rules, and MCP servers. Source: https://www.antigravity.google/docs/settings and /docs/overview (verified 2026-07-15).','https://www.antigravity.google/docs/settings and /docs/overview (verified 2026-07-15)','934186ec826ecc98729b55ae33293f65b94f27d3563719df6030ee4084ceb5e2','antigravity,config,mcp,rules',2);
INSERT OR IGNORE INTO memory_items(stable_id,kind,source,title,content,artifact_path,source_hash,tags,weight) VALUES('project:antigravity:integration-points-v1','project_doc','seed://antigravity/integration','Google Antigravity command surface Simplicio integration points','Snapshot date: 2026-07-15. T2 MCP plus rules; MCP and terminal policies are user-controlled, so integration remains additive and read-only in phase 0. Simplicio execution remains the governed control plane; provider surfaces are compatibility inputs, not alternate mutation paths. Source: https://www.antigravity.google/docs/settings and /docs/overview (verified 2026-07-15).','https://www.antigravity.google/docs/settings and /docs/overview (verified 2026-07-15)','0cab07daf2a7754644bb3c9dc1dd3d306c0c5c0c5569d52cb57d59746cb7f7e0','antigravity,simplicio,integration,governance',2);
